/*
 * EXPERIMENT 11: Robot Eye — Arduino + OLED
 * EZCirkit Learning Kit
 *
 * Draws a simple animated robot eye that looks left, right,
 * center, and blinks automatically. Touching the sensor
 * makes the eye blink extra times, like it's surprised.
 */

#include <Wire.h>
#include <Adafruit_GFX.h>
#include <Adafruit_SSD1306.h>

#define SCREEN_WIDTH 128
#define SCREEN_HEIGHT 64
#define OLED_RESET -1
Adafruit_SSD1306 display(SCREEN_WIDTH, SCREEN_HEIGHT, &Wire, OLED_RESET);

const int TOUCH_PIN = 2;      // Touch sensor tells the eye to blink

const int EYE_X = 64;         // Center of the eye on screen (x)
const int EYE_Y = 32;         // Center of the eye on screen (y)
const int EYE_RADIUS = 26;    // Size of the white part of the eye
const int PUPIL_RADIUS = 10;  // Size of the black pupil

void setup() {
  pinMode(TOUCH_PIN, INPUT);
  Serial.begin(9600);

  // Start the OLED screen. 0x3C is the usual I2C address.
  if (!display.begin(SSD1306_SWITCHCAPVCC, 0x3C)) {
    Serial.println("OLED not found! Check wiring.");
    while (true); // Stop here if the screen did not connect
  }

  display.clearDisplay();
  Serial.println("Robot Eye Started!");
}

// Draws the eye looking in a direction.
// pupilOffsetX: negative = look left, 0 = center, positive = look right
void drawEye(int pupilOffsetX) {
  display.clearDisplay();
  display.drawCircle(EYE_X, EYE_Y, EYE_RADIUS, SSD1306_WHITE);
  display.fillCircle(EYE_X + pupilOffsetX, EYE_Y, PUPIL_RADIUS, SSD1306_WHITE);
  display.display();
}

// Makes the eye close and reopen, like a blink.
void blink() {
  for (int h = 0; h <= EYE_RADIUS; h += 4) {
    display.clearDisplay();
    display.drawCircle(EYE_X, EYE_Y, EYE_RADIUS, SSD1306_WHITE);
    display.fillCircle(EYE_X, EYE_Y, PUPIL_RADIUS, SSD1306_WHITE);
    // Black bars close in from the top and bottom of the eye
    display.fillRect(EYE_X - EYE_RADIUS - 2, EYE_Y - EYE_RADIUS - 2, (EYE_RADIUS + 2) * 2, h, SSD1306_BLACK);
    display.fillRect(EYE_X - EYE_RADIUS - 2, EYE_Y + EYE_RADIUS + 2 - h, (EYE_RADIUS + 2) * 2, h, SSD1306_BLACK);
    display.display();
    delay(15);
  }
  delay(120);       // Eye stays closed for a moment
  drawEye(0);        // Reopen, looking center
}

void loop() {
  drawEye(0);         // Look center
  delay(1000);

  drawEye(-12);        // Look left
  delay(700);

  drawEye(12);         // Look right
  delay(700);

  drawEye(0);          // Back to center
  delay(1000);

  blink();             // Blink normally

  // If someone touches the sensor, blink twice quickly (surprised!)
  if (digitalRead(TOUCH_PIN) == HIGH) {
    blink();
    blink();
  }
}

