/*
 * EXPERIMENT 2: SOS Buzzer Alarm — Morse Code Distress Signal
 * EZCirkit Learning Kit
 *
 * Press the button to trigger the SOS alarm in Morse code.
 * SOS in Morse: ... --- ... (3 short, 3 long, 3 short)
 *
 * Components:
 * - Piezo Buzzer on Pin 8
 * - Push Button on Pin 2 (using INPUT_PULLUP)
 */

const int BUZZER_PIN = 8;  // Buzzer connected to pin 8
const int BUTTON_PIN = 2;  // Button connected to pin 2

// Timing constants for Morse code
const int DOT  = 150;  // Short beep duration (milliseconds)
const int DASH = 450;  // Long beep duration (milliseconds)
const int GAP  = 150;  // Gap between signals
const int LETTER_GAP = 400;  // Gap between letters

// ---- Helper Functions ----

// Play a short beep (dot in Morse code)
void playDot() {
  digitalWrite(BUZZER_PIN, HIGH);  // Buzzer ON
  delay(DOT);                      // Short duration
  digitalWrite(BUZZER_PIN, LOW);   // Buzzer OFF
  delay(GAP);                      // Gap after signal
}

// Play a long beep (dash in Morse code)
void playDash() {
  digitalWrite(BUZZER_PIN, HIGH);  // Buzzer ON
  delay(DASH);                     // Long duration
  digitalWrite(BUZZER_PIN, LOW);   // Buzzer OFF
  delay(GAP);                      // Gap after signal
}

// Play the SOS pattern: ... --- ...
void playSOS() {
  Serial.println("SOS ALERT! ... --- ...");

  // S = three dots
  playDot();
  playDot();
  playDot();
  delay(LETTER_GAP);  // Gap between letters

  // O = three dashes
  playDash();
  playDash();
  playDash();
  delay(LETTER_GAP);

  // S = three dots
  playDot();
  playDot();
  playDot();

  delay(1000);  // Pause before SOS can be triggered again
}

void setup() {
  pinMode(BUZZER_PIN, OUTPUT);         // Buzzer is an output
  pinMode(BUTTON_PIN, INPUT_PULLUP);   // Button uses internal pull-up resistor

  Serial.begin(9600);
  Serial.println("SOS Alarm Ready. Press button to trigger!");

  // Startup beep to confirm circuit works
  digitalWrite(BUZZER_PIN, HIGH);
  delay(100);
  digitalWrite(BUZZER_PIN, LOW);
  Serial.println("Startup beep OK");
}

void loop() {
  // Read button state — LOW means pressed (INPUT_PULLUP logic)
  int buttonState = digitalRead(BUTTON_PIN);

  if (buttonState == LOW) {
    // Button is pressed — trigger SOS alarm
    playSOS();
  } else {
    // Button not pressed — stay silent
    Serial.println("Waiting for button press...");
    delay(200);  // Check every 200ms to reduce Serial spam
  }
}

