/*
 * EXPERIMENT 4: Smart Fire Alarm
 * EZCirkit Learning Kit
 *
 * The flame sensor detects fire using infrared light.
 * IMPORTANT: Flame sensor is ACTIVE LOW.
 *   - DO pin reads LOW  = Flame detected (DANGER!)
 *   - DO pin reads HIGH = No flame (Safe)
 *
 * Components:
 * - Flame Sensor digital output on Pin 7
 * - Piezo Buzzer on Pin 8
 * - Red LED alarm light on Pin 6
 */

const int FLAME_PIN  = 7;   // Flame sensor digital output
const int BUZZER_PIN = 8;   // Alarm buzzer
const int LED_PIN    = 6;   // Red alarm LED

// Alarm timing
const int ALARM_BEEP_ON  = 100;  // Beep duration (ms)
const int ALARM_BEEP_OFF = 100;  // Gap between beeps (ms)
const int ALARM_BEEPS    = 5;    // Beeps per alarm cycle

// System status
int alarmCount = 0;  // How many alarm events detected

// Function: Blink LED and sound buzzer rapidly for alarm
void triggerAlarm() {
  alarmCount++;
  Serial.print("!!! FIRE DETECTED !!! Alarm #");
  Serial.println(alarmCount);

  // Flash and beep rapidly
  for (int i = 0; i < ALARM_BEEPS; i++) {
    digitalWrite(BUZZER_PIN, HIGH);   // Buzzer ON
    digitalWrite(LED_PIN, HIGH);      // LED ON
    delay(ALARM_BEEP_ON);

    digitalWrite(BUZZER_PIN, LOW);    // Buzzer OFF
    digitalWrite(LED_PIN, LOW);       // LED OFF
    delay(ALARM_BEEP_OFF);
  }
}

// Function: Normal standby — LED glows softly
void standbyMode() {
  // Slow gentle pulse to show system is active
  analogWrite(LED_PIN, 30);   // Very dim glow
  Serial.println("System OK — No flame detected.");
  delay(1000);
}

void setup() {
  pinMode(FLAME_PIN, INPUT);     // Sensor output is our input
  pinMode(BUZZER_PIN, OUTPUT);   // Buzzer is output
  pinMode(LED_PIN, OUTPUT);      // LED is output

  Serial.begin(9600);
  Serial.println("Smart Fire Alarm System Ready");
  Serial.println("WARNING: Sensor is ACTIVE LOW — LOW signal means fire!");

  // Startup sequence: three quick beeps to confirm working
  for (int i = 0; i < 3; i++) {
    digitalWrite(BUZZER_PIN, HIGH);
    delay(80);
    digitalWrite(BUZZER_PIN, LOW);
    delay(80);
  }
  Serial.println("Self-test complete. Monitoring for fire...");
}

void loop() {
  // Read flame sensor — LOW means flame detected (active low)
  int flameReading = digitalRead(FLAME_PIN);

  if (flameReading == LOW) {
    // FIRE DETECTED — trigger alarm
    triggerAlarm();

    // Keep alarming as long as flame is present
    while (digitalRead(FLAME_PIN) == LOW) {
      digitalWrite(BUZZER_PIN, HIGH);
      digitalWrite(LED_PIN, HIGH);
      delay(100);
      digitalWrite(BUZZER_PIN, LOW);
      digitalWrite(LED_PIN, LOW);
      delay(100);
    }

    // Flame gone — all clear
    Serial.println("All clear — flame no longer detected.");
    Serial.print("Total alarm events: ");
    Serial.println(alarmCount);

  } else {
    // Safe — show standby status
    standbyMode();
  }
}

