/*
 * EXPERIMENT 10: Home Security System — Capstone Project
 * EZCirkit Learning Kit
 *
 * A complete multi-zone security and safety alarm system.
 *
 * Zones:
 *   Zone 1 — PERIMETER (Touch Sensor)  : Detects intrusion
 *   Zone 2 — FIRE     (Flame Sensor)   : Detects fire/flame
 *   Zone 3 — OVERHEAT (DHT11 Sensor)   : Detects overtemperature
 *
 * OLED displays real-time status for all zones.
 * Button resets active alarms (requires all triggers to be cleared first).
 *
 * Libraries needed: DHT sensor library, Adafruit SSD1306, Adafruit GFX
 */

#include <Wire.h>
#include <Adafruit_GFX.h>
#include <Adafruit_SSD1306.h>
#include <DHT.h>

// ---- Display ----
#define SCREEN_WIDTH  128
#define SCREEN_HEIGHT  64
#define OLED_RESET     -1
#define SCREEN_ADDRESS 0x3C
Adafruit_SSD1306 display(SCREEN_WIDTH, SCREEN_HEIGHT, &Wire, OLED_RESET);

// ---- DHT11 ----
#define DHT_PIN  2
DHT dht(DHT_PIN, DHT11);

// ---- Input Pins ----
const int TOUCH_PIN  = 3;   // TTP223 capacitive touch sensor
const int FLAME_PIN  = 7;   // Flame sensor (active LOW)
const int RESET_PIN  = 4;   // Manual reset button (INPUT_PULLUP)

// ---- Output Pins ----
const int BUZZER_PIN    = 8;   // Alarm buzzer
const int LED_TOUCH     = 9;   // Zone 1 indicator LED
const int LED_FIRE      = 10;  // Zone 2 indicator LED
const int LED_OVERHEAT  = 11;  // Zone 3 indicator LED

// ---- Thresholds ----
const float OVERHEAT_THRESHOLD = 38.0;  // Celsius — alarm if above this

// ---- System State ----
enum AlarmState { NORMAL, ARMED, ALARM };
AlarmState systemState = NORMAL;

bool alarmTouch    = false;
bool alarmFire     = false;
bool alarmOverheat = false;

float currentTemp  = 0;
float currentHumid = 0;
int   alarmBeepCount = 0;

// ---- OLED Drawing Functions ----

void drawStatusScreen() {
  display.clearDisplay();
  display.setTextSize(1);
  display.setTextColor(WHITE);

  // Header
  display.setCursor(10, 0);
  display.print("HOME SECURITY SYSTEM");
  display.drawLine(0, 9, 127, 9, WHITE);

  // Zone 1: Perimeter
  display.setCursor(0, 12);
  display.print("Z1-PERIMETER: ");
  display.print(alarmTouch ? "ALARM!" : "SAFE ");

  // Zone 2: Fire
  display.setCursor(0, 23);
  display.print("Z2-FIRE     : ");
  display.print(alarmFire ? "ALARM!" : "SAFE ");

  // Zone 3: Overheat
  display.setCursor(0, 34);
  display.print("Z3-OVERHEAT : ");
  display.print(alarmOverheat ? "ALARM!" : "SAFE ");

  // Temperature readout
  display.setCursor(0, 47);
  display.print("Temp: ");
  display.print(currentTemp, 1);
  display.print("C  Hum:");
  display.print((int)currentHumid);
  display.print("%");

  // System status bar
  display.drawLine(0, 56, 127, 56, WHITE);
  display.setCursor(0, 58);
  if (systemState == NORMAL) {
    display.print("STATUS: MONITORING");
  } else if (systemState == ALARM) {
    display.print("!!! ALARM ACTIVE !!!");
  }

  display.display();
}

// ---- Alarm Functions ----

void soundAlarm() {
  // Alternating high-low beep pattern
  for (int i = 0; i < 2; i++) {
    digitalWrite(BUZZER_PIN, HIGH);
    delay(80);
    digitalWrite(BUZZER_PIN, LOW);
    delay(80);
  }
  alarmBeepCount++;
}

void flashAlarmLEDs() {
  // Flash only the triggered zone LEDs
  if (alarmTouch)    digitalWrite(LED_TOUCH, HIGH);
  if (alarmFire)     digitalWrite(LED_FIRE, HIGH);
  if (alarmOverheat) digitalWrite(LED_OVERHEAT, HIGH);
  delay(200);
  if (alarmTouch)    digitalWrite(LED_TOUCH, LOW);
  if (alarmFire)     digitalWrite(LED_FIRE, LOW);
  if (alarmOverheat) digitalWrite(LED_OVERHEAT, LOW);
  delay(200);
}

void resetSystem() {
  // Only reset if no triggers are currently active
  bool touchActive    = (digitalRead(TOUCH_PIN) == HIGH);
  bool flameActive    = (digitalRead(FLAME_PIN)  == LOW);
  float t = dht.readTemperature();
  bool overheatActive = (!isnan(t) && t > OVERHEAT_THRESHOLD);

  if (!touchActive && !flameActive && !overheatActive) {
    alarmTouch    = false;
    alarmFire     = false;
    alarmOverheat = false;
    systemState   = NORMAL;
    alarmBeepCount = 0;

    // All LEDs off
    digitalWrite(LED_TOUCH, LOW);
    digitalWrite(LED_FIRE, LOW);
    digitalWrite(LED_OVERHEAT, LOW);
    digitalWrite(BUZZER_PIN, LOW);

    Serial.println("System RESET — all zones clear.");

    // Confirmation beep pattern
    for (int i = 0; i < 3; i++) {
      digitalWrite(BUZZER_PIN, HIGH);
      delay(60);
      digitalWrite(BUZZER_PIN, LOW);
      delay(60);
    }
  } else {
    Serial.println("Cannot reset — triggers still active!");
    // Error beep
    digitalWrite(BUZZER_PIN, HIGH);
    delay(500);
    digitalWrite(BUZZER_PIN, LOW);
  }
}

void setup() {
  // Inputs
  pinMode(TOUCH_PIN, INPUT);
  pinMode(FLAME_PIN, INPUT);
  pinMode(RESET_PIN, INPUT_PULLUP);

  // Outputs
  pinMode(BUZZER_PIN, OUTPUT);
  pinMode(LED_TOUCH, OUTPUT);
  pinMode(LED_FIRE, OUTPUT);
  pinMode(LED_OVERHEAT, OUTPUT);

  // Ensure all outputs start OFF
  digitalWrite(BUZZER_PIN, LOW);
  digitalWrite(LED_TOUCH, LOW);
  digitalWrite(LED_FIRE, LOW);
  digitalWrite(LED_OVERHEAT, LOW);

  Serial.begin(9600);
  dht.begin();

  // Initialize OLED
  if (!display.begin(SSD1306_SWITCHCAPVCC, SCREEN_ADDRESS)) {
    Serial.println("OLED not found! Check wiring.");
    while (true);
  }

  // Splash screen
  display.clearDisplay();
  display.setTextSize(1);
  display.setCursor(15, 10);
  display.println("EZCirkit Security");
  display.setCursor(25, 25);
  display.println("System v1.0");
  display.setCursor(20, 45);
  display.println("Initializing...");
  display.display();

  Serial.println("Security System Booting...");
  delay(2000);

  // Self-test: flash all LEDs and beep
  digitalWrite(LED_TOUCH, HIGH);
  digitalWrite(LED_FIRE, HIGH);
  digitalWrite(LED_OVERHEAT, HIGH);
  digitalWrite(BUZZER_PIN, HIGH);
  delay(300);
  digitalWrite(LED_TOUCH, LOW);
  digitalWrite(LED_FIRE, LOW);
  digitalWrite(LED_OVERHEAT, LOW);
  digitalWrite(BUZZER_PIN, LOW);

  Serial.println("Self-test complete. System armed and monitoring.");
  systemState = NORMAL;
}

void loop() {
  // ---- Read all sensors ----
  bool touchDetected = (digitalRead(TOUCH_PIN) == HIGH);
  bool flameDetected = (digitalRead(FLAME_PIN) == LOW);   // Active LOW

  float t = dht.readTemperature();
  float h = dht.readHumidity();
  if (!isnan(t)) currentTemp  = t;
  if (!isnan(h)) currentHumid = h;
  bool overheatDetected = (currentTemp > OVERHEAT_THRESHOLD);

  // ---- Zone 1: Perimeter (Touch Sensor) ----
  if (touchDetected && !alarmTouch) {
    alarmTouch  = true;
    systemState = ALARM;
    Serial.println("ZONE 1 ALARM: Perimeter breach detected!");
  }

  // ---- Zone 2: Fire (Flame Sensor) ----
  if (flameDetected && !alarmFire) {
    alarmFire   = true;
    systemState = ALARM;
    Serial.println("ZONE 2 ALARM: FIRE DETECTED!");
  }

  // ---- Zone 3: Overheat (DHT11) ----
  if (overheatDetected && !alarmOverheat) {
    alarmOverheat = true;
    systemState   = ALARM;
    Serial.print("ZONE 3 ALARM: Temperature critical — ");
    Serial.print(currentTemp);
    Serial.println("C");
  }

  // ---- Trigger alarm outputs if any zone active ----
  if (systemState == ALARM) {
    flashAlarmLEDs();
    soundAlarm();
  }

  // ---- Check reset button ----
  if (digitalRead(RESET_PIN) == LOW) {
    delay(50);  // Debounce
    resetSystem();
    delay(200);
  }

  // ---- Update OLED display ----
  drawStatusScreen();

  // ---- Serial status report every 5 seconds ----
  static unsigned long lastReport = 0;
  if (millis() - lastReport > 5000) {
    Serial.print("Temp: ");    Serial.print(currentTemp);
    Serial.print("C  Hum: ");  Serial.print(currentHumid);
    Serial.print("%  State: ");
    Serial.println(systemState == ALARM ? "ALARM" : "NORMAL");
    lastReport = millis();
  }

  delay(100);  // Loop rate control
}

