 * EZCirkit Learning Kit
 *
 * COMMON CATHODE 7-Segment Display
 * COM pins -> GND
 * Segment ON  = HIGH
 * Segment OFF = LOW
 */

const int SEG_A = 2;
const int SEG_B = 3;
const int SEG_C = 4;
const int SEG_D = 5;
const int SEG_E = 6;
const int SEG_F = 7;
const int SEG_G = 8;

const int BUTTON_PIN = 9;

int segments[] = {
  SEG_A,
  SEG_B,
  SEG_C,
  SEG_D,
  SEG_E,
  SEG_F,
  SEG_G
};

const int numSegments = 7;

/*
   Digit Patterns
   Order: A B C D E F G
   HIGH = ON
   LOW  = OFF
*/

bool digits[6][7] = {

  //1
  {LOW, HIGH, HIGH, LOW, LOW, LOW, LOW},

  //2
  {HIGH, HIGH, LOW, HIGH, HIGH, LOW, HIGH},

  //3
  {HIGH, HIGH, HIGH, HIGH, LOW, LOW, HIGH},

  //4
  {LOW, HIGH, HIGH, LOW, LOW, HIGH, HIGH},

  //5
  {HIGH, LOW, HIGH, HIGH, LOW, HIGH, HIGH},

  //6
  {HIGH, LOW, HIGH, HIGH, HIGH, HIGH, HIGH}

};

void clearDisplay() {

  for (int i = 0; i < numSegments; i++) {
    digitalWrite(segments[i], LOW);
  }

}

void showDigit(int number) {

  if (number < 1 || number > 6)
    return;

  for (int i = 0; i < numSegments; i++) {
    digitalWrite(segments[i], digits[number - 1][i]);
  }

}

void rollAnimation(int finalNumber) {

  Serial.println("Rolling...");

  for (int cycle = 0; cycle < 15; cycle++) {

    int show = (cycle % 6) + 1;

    showDigit(show);

    if (cycle < 5)
      delay(150);
    else if (cycle < 11)
      delay(60);
    else
      delay(130);
  }

  showDigit(finalNumber);

  Serial.print("Rolled: ");
  Serial.println(finalNumber);

}

void setup() {

  for (int i = 0; i < numSegments; i++) {
    pinMode(segments[i], OUTPUT);
  }

  pinMode(BUTTON_PIN, INPUT_PULLUP);

  Serial.begin(9600);

  Serial.println("Digital Dice Ready!");
  Serial.println("Press the button to roll.");

  randomSeed(analogRead(A3));

  clearDisplay();

  // Startup dash
  digitalWrite(SEG_G, HIGH);

}

void loop() {

  if (digitalRead(BUTTON_PIN) == LOW) {

    delay(50);

    int diceRoll = random(1, 7);

    rollAnimation(diceRoll);

    while (digitalRead(BUTTON_PIN) == LOW) {
