/*
 * EXPERIMENT 1: Blink and Breathe - Your First LED
 * EZCirkit Learning Kit
 *
 * Part 1: Blink the LED on and off
 * Part 2: Make it "breathe" by fading in and out using PWM
 *
 * Pin 9 is used because it supports PWM (analogWrite)
 */

const int LED_PIN = 9;  // LED connected to pin 9 (PWM capable)

void setup() {
  // Set LED pin as an output
  pinMode(LED_PIN, OUTPUT);

  // Start serial monitor so we can see messages
  Serial.begin(9600);
  Serial.println("Experiment 1 Started!");
}

void loop() {
  // ---- PART 1: Classic Blink ----
  Serial.println("Blinking...");

  digitalWrite(LED_PIN, HIGH);   // Turn LED ON (5V)
  delay(500);                    // Wait 0.5 seconds
  digitalWrite(LED_PIN, LOW);    // Turn LED OFF (0V)
  delay(500);                    // Wait 0.5 seconds

  // Blink 5 times total
  for (int i = 0; i < 4; i++) {  // Already blinked once above, so 4 more
    digitalWrite(LED_PIN, HIGH);
    delay(500);
    digitalWrite(LED_PIN, LOW);
    delay(500);
  }

  // ---- PART 2: Breathing Effect (Fade in and out) ----
  Serial.println("Breathing...");

  // Fade IN (0 = off, 255 = full brightness)
  for (int brightness = 0; brightness <= 255; brightness += 5) {
    analogWrite(LED_PIN, brightness);  // Set brightness (0-255)
    delay(15);                          // Small delay for smooth fade
  }

  // Fade OUT (255 = full brightness, 0 = off)
  for (int brightness = 255; brightness >= 0; brightness -= 5) {
    analogWrite(LED_PIN, brightness);  // Reduce brightness
    delay(15);
  }

  delay(500);  // Pause before repeating the whole sequence
}

