/*
 * EXPERIMENT 7: Smart Plant Guardian — Soil Moisture Alert
 * EZCirkit Learning Kit
 *
 * Reads soil moisture using analog capacitive sensor.
 * Converts raw reading to 0-100% moisture percentage.
 * Alerts with LED and buzzer when soil is too dry.
 *
 * Sensor calibration values (adjust for your soil):
 *   DRY_VALUE  = reading when sensor is in dry air (~850-1023)
 *   WET_VALUE  = reading when sensor is submerged in water (~250-400)
 *
 * Components:
 * - Soil Moisture Sensor AOUT on A0
 * - Buzzer on Pin 8
 * - Red LED on Pin 9
 */

const int MOISTURE_PIN = A0;   // Analog pin for soil sensor
const int BUZZER_PIN   = 8;    // Alert buzzer
const int LED_PIN      = 9;    // Alert LED

// Calibration values — adjust after testing your sensor in dry air and water
const int DRY_VALUE = 850;   // Reading when sensor is completely dry
const int WET_VALUE = 300;   // Reading when sensor is in water

// Moisture thresholds for alerts
const int VERY_DRY    = 20;   // Below 20% = very dry — urgent watering needed
const int DRY         = 40;   // Below 40% = dry — water soon
const int COMFORTABLE = 60;   // 40-60% = good for most plants
const int WET         = 80;   // 60-80% = moist
// Above 80% = too wet — risk of overwatering

int lastMoisturePercent = -1;  // Track last reading to detect changes

// Function: Convert raw sensor reading to percentage
int convertToPercent(int rawValue) {
  // map() converts from one range to another
  // Raw: DRY_VALUE (dry) to WET_VALUE (wet)
  // Percent: 0% (dry) to 100% (wet)
  int percent = map(rawValue, DRY_VALUE, WET_VALUE, 0, 100);

  // Constrain to valid range (0-100%)
  percent = constrain(percent, 0, 100);

  return percent;
}

// Function: Print moisture status with description
void printStatus(int percent, int rawValue) {
  Serial.println("==================================");
  Serial.print("Raw Sensor Value : ");
  Serial.println(rawValue);
  Serial.print("Moisture Level   : ");
  Serial.print(percent);
  Serial.println("%");
  Serial.print("Soil Status      : ");

  if (percent < VERY_DRY) {
    Serial.println("VERY DRY — Water immediately!");
  } else if (percent < DRY) {
    Serial.println("DRY — Water your plant soon.");
  } else if (percent < COMFORTABLE) {
    Serial.println("COMFORTABLE — Good moisture level.");
  } else if (percent < WET) {
    Serial.println("MOIST — Plant is well watered.");
  } else {
    Serial.println("TOO WET — Reduce watering, risk of root rot.");
  }
}

// Function: Control LED brightness based on moisture
void setLEDFeedback(int percent) {
  if (percent < VERY_DRY) {
    // Very dry: LED on full bright as alert
    analogWrite(LED_PIN, 255);
  } else if (percent < DRY) {
    // Dry: LED at medium brightness warning
    analogWrite(LED_PIN, 100);
  } else {
    // Good moisture: LED off
    analogWrite(LED_PIN, 0);
  }
}

