/*
 * EXPERIMENT 9: Mini OLED Dashboard
 * EZCirkit Learning Kit
 *
 * Displays a multi-sensor dashboard on the 0.96" OLED screen.
 * Shows: Temperature, Humidity, Soil Moisture, System Uptime
 * Button cycles between display screens.
 *
 * Required Libraries:
 *   - Adafruit_SSD1306
 *   - Adafruit_GFX
 *   - DHT sensor library
 *
 * I2C Pins: SDA=A4, SCL=A5 (Arduino UNO hardware I2C)
 * OLED I2C Address: 0x3C (most common — change if display blank)
 */

#include <Wire.h>
#include <Adafruit_GFX.h>
#include <Adafruit_SSD1306.h>
#include <DHT.h>

// OLED display size
#define SCREEN_WIDTH  128
#define SCREEN_HEIGHT  64
#define OLED_RESET     -1       // No reset pin used
#define SCREEN_ADDRESS 0x3C     // I2C address (try 0x3D if display blank)

// Create display object
Adafruit_SSD1306 display(SCREEN_WIDTH, SCREEN_HEIGHT, &Wire, OLED_RESET);

// DHT sensor
#define DHT_PIN  2
#define DHT_TYPE DHT11
DHT dht(DHT_PIN, DHT_TYPE);

// Other pins
const int MOISTURE_PIN = A0;
const int BUTTON_PIN   = 4;

// Sensor calibration
const int DRY_VALUE = 850;
const int WET_VALUE = 300;

// Screen management
int currentScreen = 0;      // 0=Main, 1=Temperature, 2=Soil, 3=Uptime
const int NUM_SCREENS = 4;
bool lastButtonState = HIGH;

// Sensor data storage
float temperature  = 0;
float humidity     = 0;
int   soilPercent  = 0;

// Function: Read all sensors and update stored values
void readAllSensors() {
  float t = dht.readTemperature();
  float h = dht.readHumidity();

  if (!isnan(t)) temperature = t;
  if (!isnan(h)) humidity    = h;

  int raw = analogRead(MOISTURE_PIN);
  soilPercent = constrain(map(raw, DRY_VALUE, WET_VALUE, 0, 100), 0, 100);
}

// Function: Draw a progress bar on OLED
void drawBar(int x, int y, int width, int height, int percent) {
  display.drawRect(x, y, width, height, WHITE);  // Outer border
  int fill = map(percent, 0, 100, 0, width - 4); // Inner fill width
  display.fillRect(x + 2, y + 2, fill, height - 4, WHITE); // Fill bar
}

// Screen 0: Main overview — all data at once
void drawMainScreen() {
  display.clearDisplay();

  // Header
  display.setTextSize(1);
  display.setTextColor(WHITE);
  display.setCursor(20, 0);
  display.print("EZCirkit Dashboard");

  // Separator line
  display.drawLine(0, 10, 127, 10, WHITE);

  // Temperature
  display.setCursor(0, 14);
  display.print("Temp:");
  display.setCursor(35, 14);
  display.print(temperature, 1);
  display.print(" C");

  // Humidity
  display.setCursor(0, 25);
  display.print("Humi:");
  display.setCursor(35, 25);
  display.print(humidity, 1);
  display.print(" %");

  // Soil
  display.setCursor(0, 36);
  display.print("Soil:");
  display.setCursor(35, 36);
  display.print(soilPercent);
  display.print(" %");
  drawBar(70, 36, 55, 8, soilPercent);

  // Screen indicator dots at bottom
  for (int i = 0; i < NUM_SCREENS; i++) {
    if (i == currentScreen) {
      display.fillCircle(52 + i * 10, 60, 3, WHITE);  // Filled = current
    } else {
      display.drawCircle(52 + i * 10, 60, 3, WHITE);  // Outline = other
    }
  }

  display.display();  // Push buffer to screen — REQUIRED!
}

// Screen 1: Large temperature display
void drawTempScreen() {
  display.clearDisplay();
  display.setTextSize(1);
  display.setCursor(25, 0);
  display.print("TEMPERATURE");
  display.drawLine(0, 10, 127, 10, WHITE);

  // Large number
  display.setTextSize(3);
  display.setCursor(15, 20);
  display.print(temperature, 1);
  display.setTextSize(2);
  display.print("C");

  // Comfort label
  display.setTextSize(1);
  display.setCursor(30, 55);
  if (temperature > 35) display.print("Too Hot!");
  else if (temperature < 15) display.print("Too Cold!");
  else display.print("Comfortable");

  display.display();
}

// Screen 2: Soil moisture with large bar
void drawSoilScreen() {
  display.clearDisplay();
  display.setTextSize(1);
  display.setCursor(20, 0);
  display.print("SOIL MOISTURE");
  display.drawLine(0, 10, 127, 10, WHITE);

  // Large percent number
  display.setTextSize(3);
  display.setCursor(30, 18);
  display.print(soilPercent);
  display.print("%");

  // Large progress bar
  drawBar(10, 48, 108, 12, soilPercent);

  // Status label
  display.setTextSize(1);
  if (soilPercent < 30) {
    display.setCursor(35, 36);
    display.print("NEEDS WATER");
  } else if (soilPercent > 75) {
    display.setCursor(40, 36);
    display.print("TOO WET");
  } else {
    display.setCursor(45, 36);
    display.print("HEALTHY");
  }

  display.display();
}

// Screen 3: System uptime
void drawUptimeScreen() {
  display.clearDisplay();
  display.setTextSize(1);
  display.setCursor(35, 0);
  display.print("UPTIME");
  display.drawLine(0, 10, 127, 10, WHITE);

  unsigned long ms = millis();
  int seconds = (ms / 1000) % 60;
  int minutes = (ms / 60000) % 60;
  int hours   = ms / 3600000;

  display.setTextSize(2);
  display.setCursor(20, 20);
  if (hours < 10) display.print("0");
  display.print(hours);
  display.print(":");
  if (minutes < 10) display.print("0");
  display.print(minutes);
  display.print(":");
  if (seconds < 10) display.print("0");
  display.print(seconds);

  display.setTextSize(1);
  display.setCursor(15, 50);
  display.print("HH : MM : SS");

  display.display();
}

void setup() {
  pinMode(BUTTON_PIN, INPUT_PULLUP);
  Serial.begin(9600);

  // Initialize OLED display
  if (!display.begin(SSD1306_SWITCHCAPVCC, SCREEN_ADDRESS)) {
    Serial.println("ERROR: OLED display not found!");
    Serial.println("Check: VCC, GND, SDA (A4), SCL (A5) connections.");
    Serial.println("Try changing SCREEN_ADDRESS from 0x3C to 0x3D.");
    while (true);  // Halt — display required
  }

  dht.begin();

  // Splash screen
  display.clearDisplay();
  display.setTextSize(2);
  display.setTextColor(WHITE);
  display.setCursor(10, 10);
  display.println("EZCirkit");
  display.setTextSize(1);
  display.setCursor(20, 35);
  display.println("Learning Kit v1.0");
  display.setCursor(15, 50);
  display.println("Initializing...");
  display.display();
  delay(2000);

  Serial.println("OLED Dashboard Ready. Press button to switch screens.");
}

void loop() {
  // Check button for screen switching (edge detection)
  bool btnState = digitalRead(BUTTON_PIN);
  if (btnState == LOW && lastButtonState == HIGH) {
    currentScreen = (currentScreen + 1) % NUM_SCREENS;
    Serial.print("Switched to screen: ");
    Serial.println(currentScreen);
    delay(50);  // Debounce
  }
  lastButtonState = btnState;

  // Read sensors every 2.5 seconds
  static unsigned long lastRead = 0;
  if (millis() - lastRead > 2500) {
    readAllSensors();
    lastRead = millis();
  }

  // Draw current screen
  switch (currentScreen) {
    case 0: drawMainScreen();  break;
    case 1: drawTempScreen();  break;
    case 2: drawSoilScreen();  break;
    case 3: drawUptimeScreen(); break;
  }

  delay(100);
}

