/*
 * EXPERIMENT 3: Touch-Activated Magic Light
 * EZCirkit Learning Kit
 *
 * Each touch on the TTP223 sensor toggles the LED on or off.
 * Uses edge detection — only responds to a NEW touch, not holding.
 *
 * Components:
 * - TTP223 Touch Sensor on Pin 4
 * - Red LED on Pin 9 (with 330 Ohm resistor)
 */

const int TOUCH_PIN = 4;   // TTP223 output connected to pin 4
const int LED_PIN   = 9;   // LED connected to pin 9

// State variables
bool ledState     = false;  // Current LED state (false = OFF)
bool lastTouch    = false;  // Previous touch sensor state
int  touchCount   = 0;      // Count how many times user has touched

void setup() {
  pinMode(TOUCH_PIN, INPUT);   // Touch sensor output is our input
  pinMode(LED_PIN, OUTPUT);    // LED is our output

  digitalWrite(LED_PIN, LOW);  // Start with LED OFF

  Serial.begin(9600);
  Serial.println("Touch the sensor to toggle the light!");
}

void loop() {
  // Read current touch state — HIGH means finger is touching
  bool currentTouch = (digitalRead(TOUCH_PIN) == HIGH);

  // EDGE DETECTION: Respond only when touch state CHANGES from false to true
  // This prevents holding your finger on the sensor from rapidly toggling
  if (currentTouch == true && lastTouch == false) {

    // Toggle the LED state
    ledState = !ledState;   // Flip: if true->false, if false->true
    touchCount++;           // Count this touch

    // Apply the new LED state
    if (ledState) {
      digitalWrite(LED_PIN, HIGH);    // LED ON
      Serial.print("Touch #");
      Serial.print(touchCount);
      Serial.println(" — Light ON");
    } else {
      digitalWrite(LED_PIN, LOW);     // LED OFF
      Serial.print("Touch #");
      Serial.print(touchCount);
      Serial.println(" — Light OFF");
    }

    delay(50);  // Small debounce delay to prevent double-triggering
  }

  // Save current touch state for comparison next loop iteration
  lastTouch = currentTouch;

  delay(10);  // Short delay for loop stability
}

