/*
 * EXPERIMENT 6: Personal Weather Station
 * EZCirkit Learning Kit
 *
 * Reads temperature and humidity from DHT11 sensor.
 * Displays readings on Serial Monitor every 2 seconds.
 * Triggers alarm LED and buzzer if temperature exceeds threshold.
 *
 * Required library: DHT sensor library by Adafruit
 * Install via: Sketch -> Include Library -> Manage Libraries -> "DHT sensor library"
 */

#include <DHT.h>   // Include the DHT sensor library

// ---- Pin Definitions ----
#define DHT_PIN     2   // DHT11 data pin
#define DHT_TYPE    DHT11  // Sensor type: DHT11 (not DHT22)

const int STATUS_LED  = 9;   // Normal status indicator LED
const int ALARM_LED   = 6;   // High temperature alarm LED
const int BUZZER_PIN  = 8;   // Alarm buzzer

// ---- Threshold Settings ----
const float TEMP_HIGH    = 35.0;  // Alarm if temp above this (degrees C)
const float TEMP_LOW     = 10.0;  // Warning if temp below this
const float HUMID_HIGH   = 80.0;  // Warning if humidity above this
const float HUMID_LOW    = 20.0;  // Warning if humidity below this

// ---- Create DHT sensor object ----
DHT dht(DHT_PIN, DHT_TYPE);

// ---- Variables ----
int readingCount = 0;  // Track how many readings taken

// Function: Print a formatted reading to Serial Monitor
void printReading(float temp, float humidity) {
  readingCount++;
  Serial.println("========================================");
  Serial.print("Reading #");
  Serial.println(readingCount);
  Serial.print("Temperature : ");
  Serial.print(temp);
  Serial.println(" C");
  Serial.print("Humidity    : ");
  Serial.print(humidity);
  Serial.println(" %");

  // Calculate heat index (feels-like temperature)
  float heatIndex = dht.computeHeatIndex(temp, humidity, false);
  Serial.print("Feels Like  : ");
  Serial.print(heatIndex);
  Serial.println(" C");
  Serial.println("----------------------------------------");
}

// Function: Check thresholds and trigger alerts if needed
void checkAlerts(float temp, float humidity) {
  bool alert = false;

  if (temp > TEMP_HIGH) {
    Serial.println("ALERT: Temperature too HIGH!");
    alert = true;
  }
  if (temp < TEMP_LOW) {
    Serial.println("WARNING: Temperature too LOW!");
  }
  if (humidity > HUMID_HIGH) {
    Serial.println("WARNING: Humidity too HIGH — risk of mold!");
  }
  if (humidity < HUMID_LOW) {
    Serial.println("WARNING: Humidity too LOW — risk of static!");
  }

  if (alert) {
    // Flash alarm LED and beep
    for (int i = 0; i < 3; i++) {
      digitalWrite(ALARM_LED, HIGH);
      digitalWrite(BUZZER_PIN, HIGH);
      delay(200);
      digitalWrite(ALARM_LED, LOW);
      digitalWrite(BUZZER_PIN, LOW);
      delay(200);
    }
  } else {
    // Normal — gentle glow on status LED
    analogWrite(STATUS_LED, 40);
    Serial.println("Status: All parameters normal.");
  }
}

void setup() {
  pinMode(STATUS_LED, OUTPUT);
  pinMode(ALARM_LED, OUTPUT);
  pinMode(BUZZER_PIN, OUTPUT);

  Serial.begin(9600);
  Serial.println("EZCirkit Personal Weather Station");
  Serial.println("==================================");

  dht.begin();  // Initialize the DHT sensor

  // Startup test
  digitalWrite(STATUS_LED, HIGH);
  delay(500);
  digitalWrite(STATUS_LED, LOW);
  Serial.println("Sensor initialized. Taking readings every 2 seconds...");
  delay(2000);  // DHT11 needs initial warmup time
}

void loop() {
  // Read temperature and humidity
  float humidity    = dht.readHumidity();
  float temperature = dht.readTemperature();  // Default is Celsius

  // Check if reading failed (NaN = Not a Number means sensor error)
  if (isnan(humidity) || isnan(temperature)) {
    Serial.println("ERROR: Failed to read from DHT11 sensor!");
    Serial.println("Check: VCC connected to 5V, DATA to pin 2, GND to GND");
    digitalWrite(ALARM_LED, HIGH);  // Show error LED
    delay(2000);
    digitalWrite(ALARM_LED, LOW);
    return;  // Skip rest of loop — try again next iteration
  }

  // Valid reading received — display it
  printReading(temperature, humidity);
  checkAlerts(temperature, humidity);

  // Wait 2 seconds before next reading (DHT11 minimum interval)
  delay(2000);
}

