/*
 * EXPERIMENT 8: AutoWatering Bot — Automatic Plant Watering System
 * EZCirkit Learning Kit
 *
 * Reads soil moisture every 10 seconds.
 * If soil is dry, activates relay to run water pump for 3 seconds.
 * Then waits and re-checks moisture level.
 *
 * RELAY IS ACTIVE LOW:
 *   digitalWrite(RELAY_PIN, LOW)  = Relay ON = Pump runs
 *   digitalWrite(RELAY_PIN, HIGH) = Relay OFF = Pump stops
 *
 * Safety features:
 *   - Maximum pump run time (3 seconds) to prevent overflow
 *   - Cooldown period before re-checking
 *   - Pump run counter to track total activations
 */

const int MOISTURE_PIN = A0;  // Soil sensor analog output
const int RELAY_PIN    = 7;   // Relay control pin
const int LED_PIN      = 9;   // Status LED
const int BUZZER_PIN   = 8;   // Alert buzzer

// Calibrated moisture thresholds (adjust for your sensor)
const int DRY_VALUE = 850;    // Sensor reading = completely dry
const int WET_VALUE = 300;    // Sensor reading = saturated

// Control settings
const int WATER_THRESHOLD  = 35;   // Water when moisture below 35%
const int PUMP_DURATION    = 3000; // Pump runs for 3 seconds max
const int CHECK_INTERVAL   = 10000;// Check soil every 10 seconds
const int COOLDOWN         = 15000;// Wait 15 seconds after watering

int pumpActivations = 0;   // Track total pump runs

// Convert raw analog reading to moisture percentage
int getMoisturePercent() {
  int raw = analogRead(MOISTURE_PIN);
  int pct = map(raw, DRY_VALUE, WET_VALUE, 0, 100);
  return constrain(pct, 0, 100);
}

// Run the pump for a fixed duration
void runPump(int durationMs) {
  pumpActivations++;
  Serial.print("Pump ON — watering for ");
  Serial.print(durationMs / 1000);
  Serial.println(" seconds...");

  // Active low relay: LOW = ON
  digitalWrite(RELAY_PIN, LOW);
  digitalWrite(LED_PIN, HIGH);    // LED on while pumping

  // Beep to announce pump start
  digitalWrite(BUZZER_PIN, HIGH);
  delay(200);
  digitalWrite(BUZZER_PIN, LOW);

  delay(durationMs);  // Wait for pump duration

  // Turn pump OFF
  digitalWrite(RELAY_PIN, HIGH);  // HIGH = relay OFF
  digitalWrite(LED_PIN, LOW);

  Serial.print("Pump OFF. Total activations: ");
  Serial.println(pumpActivations);
}

void setup() {
  pinMode(RELAY_PIN, OUTPUT);
  pinMode(LED_PIN, OUTPUT);
  pinMode(BUZZER_PIN, OUTPUT);

  // CRITICAL: Initialize relay to OFF state immediately
  // Active low relay — HIGH = OFF
  digitalWrite(RELAY_PIN, HIGH);

  Serial.begin(9600);
  Serial.println("AutoWatering Bot Started");
  Serial.println("========================");
  Serial.print("Water when moisture below: ");
  Serial.print(WATER_THRESHOLD);
  Serial.println("%");
  Serial.print("Pump duration: ");
  Serial.print(PUMP_DURATION / 1000);
  Serial.println(" seconds per cycle");

  // Startup confirmation beep
  digitalWrite(BUZZER_PIN, HIGH);
  delay(100);
  digitalWrite(BUZZER_PIN, LOW);
  delay(100);
  digitalWrite(BUZZER_PIN, HIGH);
  delay(100);
  digitalWrite(BUZZER_PIN, LOW);

  delay(2000); // Allow sensor to stabilize
}

void loop() {
  int moisture = getMoisturePercent();
  int rawVal   = analogRead(MOISTURE_PIN);

  Serial.println("----------------------------");
  Serial.print("Soil Moisture : ");
  Serial.print(moisture);
  Serial.println("%");
  Serial.print("Raw Reading   : ");
  Serial.println(rawVal);

  if (moisture < WATER_THRESHOLD) {
    Serial.println("Soil is DRY — activating pump!");

    // Flash LED to warn before pumping
    for (int i = 0; i < 3; i++) {
      digitalWrite(LED_PIN, HIGH);
      delay(200);
      digitalWrite(LED_PIN, LOW);
      delay(200);
    }

    runPump(PUMP_DURATION);

    Serial.println("Cooldown period — waiting before re-check...");
    delay(COOLDOWN);  // Wait for water to absorb into soil

  } else {
    Serial.println("Moisture OK — no watering needed.");
    // Gentle dim glow to show system is active
    analogWrite(LED_PIN, 20);
    delay(CHECK_INTERVAL);
    analogWrite(LED_PIN, 0);
  }
}
